import{_ as i,o as s,c as l,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Messenger V2: The New Ceph Wire Protocol - Ricardo Dias, SUSE Linux","description":"","frontmatter":{"title":"Messenger V2: The New Ceph Wire Protocol - Ricardo Dias, SUSE Linux","date":"2019-05-24T00:00:00.000Z","updated":"2019-05-24T00:00:00.000Z","tags":["Ceph","Messenger V2","Wire Protocol","Ceph Storage","Distributed Storage"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/Messenger_V2_-_The_New_Ceph_Wire_Protocol_-_Ricardo_Dias_SUSE_Linux.md","filePath":"posts/2019/Messenger_V2_-_The_New_Ceph_Wire_Protocol_-_Ricardo_Dias_SUSE_Linux.md","lastUpdated":1780459816000}'),o={name:"posts/2019/Messenger_V2_-_The_New_Ceph_Wire_Protocol_-_Ricardo_Dias_SUSE_Linux.md"};function t(n,e,_,a,p,g){return s(),l("div",null,[...e[0]||(e[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>： 新SEF信使协议（Messenger v2）介绍及配置</p><p><strong>参会人员</strong>： Ricardo Dias（SUSE Linux高级软件工程师）</p><p><strong>会议内容</strong>：</p><p><strong>1. SEF信使组件简介</strong></p><ul><li>SEF信使是Ceph集群内部组件间通信的通信库。</li><li>该组件存在于服务器守护进程（如Mon、OSD等）和客户端库（如librgw、libcephfs等）中。</li><li>信使抽象了物理通信技术，工作在传输层之上，确保消息可靠交付，并处理连接故障。</li></ul><p><strong>2. 新协议的需求</strong></p><ul><li>Messenger v1协议存在扩展性差、安全性不足等问题。</li><li>新协议（Messenger v2）旨在解决这些问题，并支持以下特性： <ul><li>可扩展性：允许在不破坏现有版本的情况下扩展协议。</li><li>多种认证方案：支持多种认证方式，包括无认证、suffix认证等。</li><li>加密：支持端到端加密，保证数据安全。</li><li>结构化消息：消息结构清晰，易于维护。</li></ul></li></ul><p><strong>3. Messenger v2协议工作原理</strong></p><ul><li>协议分为四个阶段：交换信息、认证、会话建立和消息交换。</li><li>交换信息阶段，客户端和服务器交换支持的特性和所需功能。</li><li>认证阶段，客户端和服务器协商认证方式和连接模式。</li><li>会话建立阶段，客户端和服务器交换身份信息，并生成会话cookie。</li><li>消息交换阶段，客户端和服务器可以发送和接收消息。</li></ul><p><strong>4. 加密模式</strong></p><ul><li>如果协议协商使用安全模式，则所有消息将进行加密和签名。</li><li>使用AES 128 GCM算法进行加密，保证数据的机密性和完整性。</li></ul><p><strong>5. 配置和管理</strong></p><ul><li>需要配置地址向量，指定每个守护进程监听的端口号。</li><li>新增配置选项，包括messenger1和messenger2，用于控制监听协议版本。</li><li>默认启用messenger v2，可以通过配置文件禁用。</li></ul><p><strong>6. 升级</strong></p><ul><li>从Luminous或Mimic版本升级到Nautilus版本时，需要启用messenger v2。</li><li>使用<code>safe mon messenger2</code>命令启用messenger v2。</li></ul><p><strong>7. 问题解答</strong></p><ul><li>使用CRC32进行完整性检查。</li><li>加密模式对性能有一定影响，具体影响待测试。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>完成性能测试，评估加密模式对性能的影响。</li><li>撰写文档，详细介绍新协议的配置和管理方法。</li></ul>',20)])])}const d=i(o,[["render",t]]);export{c as __pageData,d as default};
